import '../../src/styles/index.css';
import '../../src/styles/atelier.css';
import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';import RundownEditor from '../../src/components/RundownEditor.jsx';import ViridariumTemplate from '../../src/components/templates/viridarium/ViridariumTemplate.jsx';import {UIProvider} from '../../src/context/UIContext.jsx';import {api} from '../../src/api/client.js';import {mergePreviewOverride} from '../../src/utils/mergePreviewOverride.js';
const initial={id:'rundown-qa',themeId:'garden-canvas',themeSettings:{characterSettings:{mode:'default'}},coupleProfile:{brideName:'A',groomName:'B'},invitationFeatures:{rundownEnabled:true},rundowns:[{id:'one',time:'08:00 – 09:00',activity:'Akad',description:'Mohon hadir tepat waktu.',order:0},{id:'two',time:'11:00 – 13:00',activity:'Resepsi',description:'Makan bersama dan ramah tamah.',order:1}]};
api.post=async(url,payload)=>({data:{rundown:{...payload,id:'new-qa'}}});api.patch=async(url,payload)=>({data:{rundown:{...payload,id:url.split('/').pop()}}});
function App(){const [inv,setInv]=useState(initial),[patch,setPatch]=useState(null);const wrap=useRef(null);function open(){const w=wrap.current.querySelector('iframe').contentWindow;w.document.querySelector('#open').click();setTimeout(()=>w.document.querySelector('.section-dot[data-scene="rundown"]').click(),4000)}return <UIProvider><div className="atelier-app" style={{display:'grid',gridTemplateColumns:'420px 390px',gap:30}}><div className="panel" style={{padding:20,background:'#faf8ef'}}><RundownEditor invitation={inv} onUpdated={setInv} onLivePreview={setPatch}/></div><div><button onClick={open}>Buka rundown di preview</button><div ref={wrap} style={{width:390,height:844,position:'relative'}}><ViridariumTemplate invitation={mergePreviewOverride(inv,patch)}/></div></div></div></UIProvider>}
createRoot(document.getElementById('root')).render(<App/>);
